CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(100) PRIMARY KEY, applied_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS portal_users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE,
 role ENUM('student','trainer','admin') NOT NULL, password_hash VARCHAR(255) NULL,
 status ENUM('invited','active','disabled') NOT NULL DEFAULT 'invited', temporary_hash VARCHAR(255) NULL,
 temporary_expires DATETIME NULL, activation_version INT NOT NULL DEFAULT 1,
 mfa_secret VARCHAR(255) NULL, mfa_last_counter BIGINT NULL, created_at DATETIME NOT NULL
);
CREATE TABLE IF NOT EXISTS portal_login_attempts (fingerprint CHAR(64) PRIMARY KEY, attempts INT NOT NULL, last_attempt DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS portal_cohorts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL);
CREATE TABLE IF NOT EXISTS portal_memberships (cohort_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(cohort_id,user_id), FOREIGN KEY(cohort_id) REFERENCES portal_cohorts(id), FOREIGN KEY(user_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_sessions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cohort_id BIGINT UNSIGNED NOT NULL, trainer_id BIGINT UNSIGNED NOT NULL,
 title VARCHAR(180) NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL,
 mode ENUM('onsite','remote','company') NOT NULL DEFAULT 'onsite', location VARCHAR(180) NOT NULL, meeting_url VARCHAR(500) NULL,
 FOREIGN KEY(cohort_id) REFERENCES portal_cohorts(id), FOREIGN KEY(trainer_id) REFERENCES portal_users(id), INDEX(starts_at,ends_at)
);
CREATE TABLE IF NOT EXISTS portal_unavailability (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, trainer_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, reason VARCHAR(250) NOT NULL, FOREIGN KEY(trainer_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_windows (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, session_id BIGINT UNSIGNED NOT NULL, opened_by BIGINT UNSIGNED NOT NULL, opens_at DATETIME NOT NULL, closes_at DATETIME NOT NULL, FOREIGN KEY(session_id) REFERENCES portal_sessions(id), FOREIGN KEY(opened_by) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_attendance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, window_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, status ENUM('declared','validated','late','absent','excused') NOT NULL, declared_at DATETIME NULL, updated_at DATETIME NOT NULL, UNIQUE(window_id,student_id), FOREIGN KEY(window_id) REFERENCES portal_windows(id), FOREIGN KEY(student_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cohort_id BIGINT UNSIGNED NOT NULL, trainer_id BIGINT UNSIGNED NOT NULL, session_id BIGINT UNSIGNED NULL, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, due_at DATETIME NOT NULL, max_grade DECIMAL(6,2) NOT NULL DEFAULT 20, FOREIGN KEY(cohort_id) REFERENCES portal_cohorts(id), FOREIGN KEY(trainer_id) REFERENCES portal_users(id), FOREIGN KEY(session_id) REFERENCES portal_sessions(id));
CREATE TABLE IF NOT EXISTS portal_resources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cohort_id BIGINT UNSIGNED NOT NULL, session_id BIGINT UNSIGNED NULL, author_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, stored_name VARCHAR(100) NOT NULL, original_name VARCHAR(190) NOT NULL, mime VARCHAR(100) NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(cohort_id) REFERENCES portal_cohorts(id), FOREIGN KEY(session_id) REFERENCES portal_sessions(id), FOREIGN KEY(author_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_submissions (assignment_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, submitted_at DATETIME NOT NULL, PRIMARY KEY(assignment_id,student_id), FOREIGN KEY(assignment_id) REFERENCES portal_assignments(id), FOREIGN KEY(student_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_grades (assignment_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, value DECIMAL(6,2) NOT NULL, comment TEXT NOT NULL, published TINYINT NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL, PRIMARY KEY(assignment_id,student_id), FOREIGN KEY(assignment_id) REFERENCES portal_assignments(id), FOREIGN KEY(student_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cohort_id BIGINT UNSIGNED NOT NULL, author_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(cohort_id) REFERENCES portal_cohorts(id), FOREIGN KEY(author_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_exams (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cohort_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, starts_at DATETIME NOT NULL, location VARCHAR(180) NOT NULL, FOREIGN KEY(cohort_id) REFERENCES portal_cohorts(id));
CREATE TABLE IF NOT EXISTS portal_jury (exam_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(exam_id,user_id), FOREIGN KEY(exam_id) REFERENCES portal_exams(id), FOREIGN KEY(user_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_competencies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, exam_id BIGINT UNSIGNED NOT NULL, label VARCHAR(250) NOT NULL, FOREIGN KEY(exam_id) REFERENCES portal_exams(id));
CREATE TABLE IF NOT EXISTS portal_evaluations (competency_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, evaluator_id BIGINT UNSIGNED NOT NULL, level ENUM('not_acquired','developing','acquired') NOT NULL, comment TEXT NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(competency_id,student_id), FOREIGN KEY(competency_id) REFERENCES portal_competencies(id), FOREIGN KEY(student_id) REFERENCES portal_users(id), FOREIGN KEY(evaluator_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_journal (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cohort_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(cohort_id) REFERENCES portal_cohorts(id), FOREIGN KEY(student_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_feedback (cohort_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, rating INT NOT NULL, body TEXT NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(cohort_id,student_id), FOREIGN KEY(cohort_id) REFERENCES portal_cohorts(id), FOREIGN KEY(student_id) REFERENCES portal_users(id));
CREATE TABLE IF NOT EXISTS portal_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NOT NULL, action VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, detail TEXT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(actor_id) REFERENCES portal_users(id));
